import 'package:flutter/material.dart'  import 'package:go_router/go_router.dart'  import '../screens/login_screen.dart'  import '../screens/register_screen.dart'  import '../screens/home_screen.dart'  import '../screens/clients_screen.dart'  import '../screens/deals_screen.dart'  import '../screens/invoices_screen.dart'  import '../screens/tasks_screen.dart'  import '../screens/profile_screen.dart'  import '../screens/notifications_screen.dart'  import '../screens/bank_screen.dart'  import '../screens/svetlana_screen.dart'    final appRouter = GoRouter(    initialLocation: '/',    routes: [      GoRoute(path: '/', builder: (context, state) => const HomeScreen()),      GoRoute(path: '/login', builder: (context, state) => const LoginScreen()),      GoRoute(path: '/register', builder: (context, state) => const RegisterScreen()),      GoRoute(path: '/clients', builder: (context, state) => const ClientsScreen()),      GoRoute(path: '/deals', builder: (context, state) => const DealsScreen()),      GoRoute(path: '/invoices', builder: (context, state) => const InvoicesScreen()),      GoRoute(path: '/tasks', builder: (context, state) => const TasksScreen()),      GoRoute(path: '/profile', builder: (context, state) => const ProfileScreen()),      GoRoute(path: '/notifications', builder: (context, state) => const NotificationsScreen()),      GoRoute(path: '/bank', builder: (context, state) => const BankScreen()),      GoRoute(path: '/svetlana', builder: (context, state) => const SvetlanaScreen()),    ],  )